a=f.index(\"  IF _transfer_type = 'TRANSFER' THEN\");b=f.index('  IF _source_location_id',a);f=f[:a]+f[b:]
a=f.index('    IF NOT v_allow_negative THEN');b=f.index('\\n  END LOOP;',a);f=f[:a]+f[b:]
with p.open('a') as o:o.write('\\n'+f+'''\\nREVOKE ALL ON FUNCTION public.inventory_transfer_internal(uuid,uuid,uuid,jsonb,text,text,text,uuid) FROM PUBLIC,anon,authenticated;
